// Super admin passwords: generated by the command line (never chosen, never sent anywhere), stored only as a slow
// scrypt hash with its own salt. Checking takes the same time whether or not the username exists.
import { randomBytes, randomInt, scrypt as scryptCb, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';

const scrypt = promisify(scryptCb) as (password: string, salt: Buffer, keylen: number, options: { N: number; r: number; p: number; maxmem: number }) => Promise<Buffer>;

/** About 100 ms per check: fine for two people signing in, very slow for guessing. */
const PARAMS = { N: 2 ** 16, r: 8, p: 1 };
const KEY_BYTES = 32;
const MAXMEM = 256 * 1024 * 1024;

export async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(16);
  const hash = await scrypt(password.normalize('NFKC'), salt, KEY_BYTES, { ...PARAMS, maxmem: MAXMEM });
  return ['scrypt', PARAMS.N, PARAMS.r, PARAMS.p, salt.toString('base64'), hash.toString('base64')].join('$');
}

export async function verifyPassword(password: string, stored: string): Promise<boolean> {
  const [scheme, n, r, p, saltB64, hashB64] = stored.split('$');
  if (scheme !== 'scrypt' || !saltB64 || !hashB64) return false;
  const expected = Buffer.from(hashB64, 'base64');
  const actual = await scrypt(password.normalize('NFKC'), Buffer.from(saltB64, 'base64'), expected.length, { N: Number(n), r: Number(r), p: Number(p), maxmem: MAXMEM });
  return actual.length === expected.length && timingSafeEqual(actual, expected);
}

/** A hash of nothing, checked when the username is unknown, so the answer takes as long either way. */
let dummy: Promise<string> | null = null;
export async function spendTime(password: string): Promise<void> {
  dummy ??= hashPassword(randomBytes(12).toString('base64'));
  await verifyPassword(password, await dummy);
}

/** 24 characters from letters and digits without look-alikes (about 140 bits). */
export function generatePassword(length = 24): string {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';
  return Array.from({ length }, () => alphabet[randomInt(alphabet.length)]).join('');
}

/** The official username: "hq.<name>.<4 random>", e.g. "hq.sujal.k7m2". Not guessable from the name alone. */
export function generateUsername(name: string): string {
  const base = (name.trim().split(/\s+/)[0] ?? '').toLowerCase().normalize('NFKD').replace(/[^a-z]/g, '').slice(0, 12) || 'admin';
  const tail = Array.from({ length: 4 }, () => 'abcdefghjkmnpqrstuvwxyz23456789'[randomInt(31)]).join('');
  return `hq.${base}.${tail}`;
}
